#!/usr/bin/env node
'use strict';

// plow-contacts launcher. GENERATED by scripts/build-plugins.mjs from shared/ - do not edit
// by hand; change shared/ and run `node scripts/build-plugins.mjs`.
//
// One short process per call: no server, no network, nothing written to disk. Only the
// real read/write JXA adapter is wired here; test fakes live under shared/test and are
// never reachable from this file. The plugin serves exactly one app (`APP`): the
// agent's argv tail (`search ...`) gets the app group prepended, and every other app's
// commands are refused as unknown.
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const { main, emit } = require('../src/cli');
const { createJxaAdapter, OSASCRIPT } = require('../src/adapters/jxa');
const { loadCapabilities } = require('../src/sdef');
const { QueryError } = require('../src/errors');

const APP = 'contacts';
const NAME = 'plow-contacts';

const probe = {
  nodeVersion: () => process.version,
  platform: () => process.platform,
  osascriptPresent: () => { try { fs.accessSync(OSASCRIPT, fs.constants.X_OK); return true; } catch { return false; } },
  bundlePresent: (p) => fs.existsSync(p),
  bundleId: (p) => {
    try {
      return execFileSync('/usr/bin/plutil', ['-extract', 'CFBundleIdentifier', 'raw', '-o', '-', path.join(p, 'Contents', 'Info.plist')], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    } catch { return null; }
  },
};

const adapter = process.platform === 'darwin' && probe.osascriptPresent()
  ? createJxaAdapter()
  : { call: () => Promise.reject(new QueryError('RUNTIME_MISSING', 'macOS with /usr/bin/osascript is required.')) };

const tail = process.argv.slice(2);
const own = new Set(['help', 'doctor', '--help', '-h']);
const argv = tail.length === 0 || own.has(tail[0]) ? tail : [APP, ...tail];

main(argv, { adapter, capabilities: (k) => loadCapabilities(k), probe, apps: [APP], bare: true, name: NAME }).then((result) => {
  process.exitCode = emit(result, process.stdout, process.stderr, NAME);
});
